/* ===================== BÀI 20 · Chuyển số và xử lý nhập số ===================== */
/* Bài 20 · Chuyển số và xử lý nhập số (AMTS-EMB-002-M05-L04, X86-020) — sinh bởi tools/author/mpu8086/l20.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P20=[{"label": "Ví dụ: hai chữ số ASCII thành số 0..99", "code": "; Ví dụ 1: hai phím chữ số thành một số 0..99\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; chữ số hàng chục: '4' -> 4\n        MOV     BL, 10\n        MUL     BL                      ; AX = chục * 10\n        MOV     BH, AL\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; hàng đơn vị\n        ADD     AL, BH\n        MOV     so, AL                  ; 42 = 2Ah\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "42", "note": "Gõ 4 rồi 2 (dữ liệu nhập có sẵn). '4' − '0' = 4, MUL BL với BL = 10 cho AX = 40 (70 chu kỳ, cận dưới); '2' − '0' = 2; so = 42 = 2Ah. Đoán trước: sau MUL BL, AX bằng bao nhiêu (hệ 16)? Đáp án 0028h."}, {"label": "Ví dụ: đọc số tới Enter, n = n × 10 + d", "code": "; Ví dụ 2: đọc số không dấu tới khi gặp Enter\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX                  ; n = 0\ndoc:\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        CMP     AL, 0DH                 ; Enter: hết số\n        JE      xong\n        SUB     AL, '0'                 ; ASCII -> giá trị\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = chữ số\n        MOV     AX, 10\n        MUL     BX                      ; DX:AX = n * 10\n        ADD     AX, CX\n        MOV     BX, AX                  ; n = n * 10 + chữ số\n        JMP     doc\nxong:\n        MOV     so, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "1234\n", "note": "Gõ 1234 rồi Enter. Mỗi chữ số: n = n × 10 + d, n giữ trong BX vì MUL ghi đè AX và DX. Enter (0Dh) được kiểm trước khi trừ '0'. so = 1234 = 04D2h. Mỗi chữ số khoảng 215 chu kỳ, phần lớn là MUL. Đoán trước: sau chữ số thứ ba, BX bằng bao nhiêu (hệ 10)? Đáp án 123."}, {"label": "Lỗi: không kiểm ký tự, 12a4 thành 1694", "code": "; Ví dụ 3: cùng chương trình, gõ 12a4 (CÓ LỖI: không kiểm ký tự)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX                  ; n = 0\ndoc:\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        CMP     AL, 0DH                 ; Enter: hết số\n        JE      xong\n        SUB     AL, '0'                 ; LỖI: 'a' - '0' = 49, vẫn cộng vào\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = chữ số\n        MOV     AX, 10\n        MUL     BX                      ; DX:AX = n * 10\n        ADD     AX, CX\n        MOV     BX, AX                  ; n = n * 10 + chữ số\n        JMP     doc\nxong:\n        MOV     so, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "12a4\n", "note": "Lỗi cố ý: cùng chương trình với Ví dụ 2 nhưng gõ 12a4. Không kiểm ký tự nên 'a' − '0' = 49 được coi là một “chữ số”: ((1 × 10 + 2) × 10 + 49) × 10 + 4 = 1694 = 069Eh. Sửa: SUB AL, '0' / CMP AL, 9 / JA sai (Ví dụ 4). Đoán trước: sau SUB AL, '0' với phím a, AL bằng bao nhiêu (hệ 16)? Đáp án 31h."}, {"label": "Ví dụ: kiểm ký tự sai và tràn 16 bit", "code": "; Ví dụ 4: kiểm ký tự sai và tràn 16 bit\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      0\nkq      DB      0                       ; 0 đúng, 1 ký tự sai, 2 tràn\ntb1     DB      'Ky tu sai$'\ntb2     DB      'Tran: qua 65535$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 0DH\n        JE      xong\n        SUB     AL, '0'\n        CMP     AL, 9\n        JA      sai                     ; không phải '0'..'9'\n        MOV     CL, AL\n        MOV     CH, 0\n        MOV     AX, 10\n        MUL     BX                      ; CF = OF = 1 khi DX <> 0\n        JC      tran\n        ADD     AX, CX\n        JC      tran                    ; nhớ ra khỏi 16 bit khi cộng\n        MOV     BX, AX\n        JMP     doc\nsai:\n        MOV     kq, 1\n        MOV     DX, OFFSET tb1\n        JMP     in_tb\ntran:\n        MOV     kq, 2\n        MOV     DX, OFFSET tb2\nin_tb:\n        MOV     AH, 09H\n        INT     21H\n        JMP     het\nxong:\n        MOV     so, BX\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "70000\n", "note": "Gõ 70000. Bốn chữ số đầu cho n = 7000; chữ số thứ năm: MUL cho 70 000 > 65 535 nên DX = 1, CF = 1, JC tran nhảy. Chương trình ghi kq = 2 và in “Tran: qua 65535” bằng hàm 09h; so giữ 0. Thử gõ 12x: in “Ky tu sai”. Đoán trước: sau MUL BX ở chữ số thứ năm, DX bằng bao nhiêu? Đáp án 0001h."}, {"label": "Ví dụ: số có dấu −250 bằng NEG", "code": "; Ví dụ 5: số có dấu, dấu '-' ở đầu rồi NEG\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX\n        XOR     DI, DI                  ; DI = 1 nếu có dấu '-'\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, '-'\n        JNE     xet                     ; không có dấu: AL là phím đầu\n        INC     DI\ndoc:\n        MOV     AH, 08H\n        INT     21H\nxet:\n        CMP     AL, 0DH\n        JE      xong\n        SUB     AL, '0'\n        MOV     CL, AL\n        MOV     CH, 0\n        MOV     AX, 10\n        MUL     BX\n        ADD     AX, CX\n        MOV     BX, AX\n        JMP     doc\nxong:\n        TEST    DI, DI\n        JZ      ghi\n        NEG     BX                      ; -n = bù 2 của n\nghi:\n        MOV     so, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "-250\n", "note": "Gõ -250. Phím đầu là '-': DI = 1, đọc phần còn lại như số không dấu (250 = 00FAh), cuối cùng NEG BX cho FF06h = −250. Nếu phím đầu là chữ số, JNE xet nhảy thẳng vào phần xử lý với AL là phím đó. Đoán trước: ngay trước NEG BX, BX bằng bao nhiêu (hệ 16)? Đáp án 00FAh."}, {"label": "Ví dụ: số thành chuỗi bằng DIV 10", "code": "; Ví dụ 6: số 16 bit thành chuỗi thập phân rồi in\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      1234\nbuf     DB      5 DUP(' '), '$'         ; tối đa 5 chữ số\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, so\n        MOV     SI, OFFSET buf+5        ; sau chữ số cuối\n        MOV     BX, 10\ntach:\n        XOR     DX, DX                  ; DX:AX = số bị chia\n        DIV     BX                      ; AX = thương, DX = dư 0..9\n        ADD     DL, '0'\n        DEC     SI\n        MOV     [SI], DL                ; ghi từ phải sang trái\n        TEST    AX, AX\n        JNZ     tach                    ; còn chữ số\n        MOV     DX, SI                  ; in từ chữ số đầu tiên\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "1234 thành chuỗi: DIV BX bốn lần cho dư 4, 3, 2, 1; mỗi dư + '0' ghi vào buf từ phải sang trái. TEST AX, AX ở cuối thân vòng: thương 0 thì dừng. In bằng hàm 09h từ SI (chữ số đầu) tới '$'. Mỗi DIV 16 bit 144 chu kỳ (cận dưới). Đoán trước: sau lần DIV BX đầu tiên, DX bằng bao nhiêu? Đáp án 0004h."}, {"label": "Bẫy: DIV 8 bit cho 5000 gây lỗi chia", "code": "; Ví dụ 7: chia 5000 cho 10 bằng DIV 8 bit (BẪY)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 5000\n        MOV     BL, 10\n        DIV     BL                      ; BẪY: thương 500 không vừa AL\n        MOV     AX, 4C00H               ; (sửa: XOR DX,DX / MOV BX,10 / DIV BX)\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: DIV BL chia AX = 5000 cho 10, thương 500 không vừa AL (tối đa 255). CPU sinh lỗi chia (ngắt 0); trình mô phỏng dừng và giải thích, DOS thật in “Divide overflow”. Sửa: XOR DX, DX / MOV BX, 10 / DIV BX (thương 16 bit)."}, {"label": "Ví dụ: đọc dòng bằng INT 21h hàm 0Ah", "code": "; Ví dụ 8: đọc cả dòng bằng INT 21h hàm 0Ah rồi đổi ra số\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntoida   DB      6                       ; DOS nhận tối đa 5 ký tự + Enter\nda_go   DB      ?                       ; DOS ghi số ký tự đã gõ\nkytu    DB      6 DUP(?)                ; các ký tự, rồi 0Dh\nso      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET toida\n        MOV     AH, 0AH\n        INT     21H                     ; đọc một dòng, có hiện lên\n        MOV     CL, da_go\n        MOV     CH, 0                   ; CX = số ký tự\n        MOV     SI, OFFSET kytu\n        XOR     AX, AX\n        JCXZ    ghi                     ; dòng trống\ndoi:\n        MOV     DX, AX                  ; AX = AX * 10 bằng dịch và cộng\n        SHL     AX, 1\n        SHL     AX, 1\n        ADD     AX, DX                  ; 5n\n        SHL     AX, 1                   ; 10n\n        MOV     DL, [SI]\n        SUB     DL, '0'\n        MOV     DH, 0\n        ADD     AX, DX\n        INC     SI\n        LOOP    doi\nghi:\n        MOV     so, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "305\n", "note": "Hàm 0Ah đọc cả dòng 305 vào bộ đệm: toida = 6, DOS ghi da_go = 3, kytu = 33h 30h 35h 0Dh. Màn hình hiện 305 vì hàm 0Ah có hiện chữ. LOOP chạy da_go lần (JCXZ chặn dòng trống); nhân 10 bằng dịch và cộng. so = 305 = 0131h. Đoán trước: sau INT 21h, da_go bằng bao nhiêu? Đáp án 3."}];
const sim20=makeX86Sim(document.getElementById("x86-l20"),{id:"s20",presets:P20,file:"BAI20.ASM"});
makeX86Ex(document.getElementById("ex-l20"),sim20,[{"t": "In mã ASCII ở hệ 10", "d": "Đọc một phím bằng INT 21h hàm 08h và in mã ASCII của nó ở hệ 10 (ví dụ phím A in 65, phím z in 122), không in dấu cách hay số 0 thừa ở đầu. Code mẫu đã đưa mã vào AX và có bộ đệm buf 3 ký tự kết thúc bằng '$'. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: in mã ASCII của phím ở hệ 10\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      3 DUP(' '), '$'         ; tối đa 3 chữ số\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = mã ASCII\n        MOV     AH, 0                   ; AX = 0..255\n; Viết tiếp: tách chữ số bằng DIV 10, ghi vào buf từ phải\n; sang trái, rồi in từ chữ số đầu tiên (không in dấu cách thừa).\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "65"}, {"in": " ", "out": "32"}, {"in": "z", "out": "122"}, {"in": "0", "out": "48"}, {"in": "~", "out": "126"}, {"in": "!", "out": "33"}]}, {"t": "Đọc số có dấu, báo ký tự sai", "d": "Đọc các phím bằng INT 21h hàm 08h tới khi gặp Enter: có thể có một dấu '-' ở đầu, sau đó là các chữ số (giá trị từ −32768 tới 32767). Ghi số vào biến so dạng bù 2. Gặp ký tự khác (kể cả '-' thứ hai) thì in 'E', giữ so = 0 và kết thúc ngay. Code mẫu đọc được số không dấu nhưng chưa xử lý dấu và ký tự sai. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: đọc số có dấu, báo ký tự sai\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      0                       ; số có dấu (bù 2); giữ 0 nếu ký tự sai\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX                  ; n = 0\ndoc:\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        CMP     AL, 0DH                 ; Enter: hết số\n        JE      xong\n        SUB     AL, '0'                 ; ASCII -> giá trị\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = chữ số\n        MOV     AX, 10\n        MUL     BX                      ; DX:AX = n * 10\n        ADD     AX, CX\n        MOV     BX, AX                  ; n = n * 10 + chữ số\n        JMP     doc\nxong:\n        MOV     so, BX\n; Sửa và viết thêm: dấu '-' ở đầu (NEG), ký tự khác\n; '0'..'9' thì in 'E', giữ so = 0 và kết thúc ngay.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "-250\n", "mem": [{"at": "so", "word": 65286}]}, {"in": "123\n", "mem": [{"at": "so", "word": 123}]}, {"in": "32767\n", "mem": [{"at": "so", "word": 32767}]}, {"in": "-32768\n", "mem": [{"at": "so", "word": 32768}]}, {"in": "12x\n", "out": "E", "mem": [{"at": "so", "word": 0}]}, {"in": "--5\n", "out": "E", "mem": [{"at": "so", "word": 0}]}]}, {"t": "Đọc số nhanh hơn: nhân 10 bằng dịch", "d": "Đọc một số không dấu 0–9999 (tối đa 4 chữ số, chỉ có chữ số) bằng INT 21h hàm 08h tới khi gặp Enter và ghi vào biến so. Dòng trống cho so = 0. Code mẫu đã đúng nhưng mỗi chữ số tốn một lệnh MUL. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đọc số 0..9999 tới Enter, nhanh hơn\n; Bản này đúng nhưng mỗi chữ số tốn một lệnh MUL (118+ chu kỳ).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      ?                       ; 0..9999\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BX, BX                  ; n = 0\ndoc:\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        CMP     AL, 0DH                 ; Enter: hết số\n        JE      xong\n        SUB     AL, '0'                 ; ASCII -> giá trị\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = chữ số\n        MOV     AX, 10\n        MUL     BX                      ; DX:AX = n * 10\n        ADD     AX, CX\n        MOV     BX, AX                  ; n = n * 10 + chữ số\n        JMP     doc\nxong:\n        MOV     so, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "1234\n", "mem": [{"at": "so", "word": 1234}]}, {"in": "0\n", "mem": [{"at": "so", "word": 0}]}, {"in": "9999\n", "mem": [{"at": "so", "word": 9999}]}, {"in": "7\n", "mem": [{"at": "so", "word": 7}]}, {"in": "\n", "mem": [{"at": "so", "word": 0}]}, {"in": "1000\n", "mem": [{"at": "so", "word": 1000}]}], "perf": {"cycles": 580, "bytes": 42}}]);

makeQuiz("quiz20","score20",[{"q": "Đọc chuỗi <code>305<\/code> theo n = n × 10 + d, bắt đầu n = 0. Sau khi xử lý chữ số thứ hai, n bằng bao nhiêu?", "o": ["30", "3", "35", "305"], "a": 0, "e": "'3': n = 0 × 10 + 3 = 3; '0': n = 3 × 10 + 0 = 30. Chữ số thứ ba cho 305."}, {"q": "BX = 7000. Sau <code>MOV AX, 10<\/code> / <code>MUL BX<\/code>, các giá trị nào đúng?", "o": ["DX = 0001h, CF = 1", "DX = 0000h, CF = 0", "AX = 70000, CF = 0", "DX = 0001h, CF = 0"], "a": 0, "e": "70 000 = 1 1170h: DX = 0001h, AX = 1170h. MUL đặt CF = OF = 1 khi nửa cao (DX) khác 0, đó là dấu hiệu tràn 16 bit."}, {"q": "Bộ đệm hàm 0Ah: <code>toida DB 6<\/code> rồi <code>da_go DB ?<\/code>. Người dùng gõ <code>305<\/code> rồi Enter. DOS ghi gì vào da_go?", "o": ["4", "3", "6", "5"], "a": 1, "e": "Byte 1 là số ký tự đã gõ, không kể Enter. Enter (0Dh) được đặt sau ký tự cuối. 6 là số tối đa do chương trình đặt ở byte 0."}, {"q": "Với <code>DIV BL<\/code> và BL = 10, AX lớn nhất bằng bao nhiêu mà không gây lỗi chia?", "o": ["255", "2550", "2559", "65535"], "a": 2, "e": "Thương phải vừa AL (≤ 255): AX ≤ 255 × 10 + 9 = 2559 (thương 255, dư 9). 2560 cho thương 256, lỗi chia."}, {"q": "Vòng tách chữ số (chia 10, ghi dư) đặt <code>TEST AX, AX<\/code> / <code>JNZ tach<\/code> ở <b>cuối<\/b> thân vòng thay vì đầu. Vì sao?", "o": ["Để DIV nhanh hơn", "Để DX được xóa đúng lúc", "Vì JNZ không đặt được ở đầu vòng", "Để số 0 vẫn in ra một chữ số '0'"], "a": 3, "e": "Kiểm ở cuối thì thân chạy ít nhất một lần: 0 / 10 = 0 dư 0 ghi được '0'. Kiểm ở đầu thì với số 0 vòng không chạy và không in gì."}]);

